import { Platform } from 'react-native';

import { getFeedbackPrefs, shouldPlay } from './feedbackPrefs';

export type SoundName = 'tap' | 'treat' | 'upgrade' | 'celebrate' | 'bark' | 'sleepy' | 'new-street' | 'reward-reached' | 'walk-done';

// Generated by scripts/generateSounds.mjs. Lazy requires keep Jest (and web)
// from touching the asset pipeline just by importing this file.
const SOURCES: Record<SoundName, () => number> = {
  tap: () => require('../../assets/sounds/tap.wav'),
  treat: () => require('../../assets/sounds/treat.wav'),
  upgrade: () => require('../../assets/sounds/upgrade.wav'),
  celebrate: () => require('../../assets/sounds/celebrate.wav'),
  bark: () => require('../../assets/sounds/bark.wav'),
  sleepy: () => require('../../assets/sounds/sleepy.wav'),
  'new-street': () => require('../../assets/sounds/new-street.wav'),
  'reward-reached': () => require('../../assets/sounds/reward-reached.wav'),
  'walk-done': () => require('../../assets/sounds/walk-done.wav'),
};

type AvSound = { replayAsync: () => Promise<unknown> };

const loaded: Partial<Record<SoundName, AvSound>> = {};
let audioModeSet = false;
let inFlight: Promise<void> | null = null;

// Loads whatever is not loaded yet. Called on every play until every sound is
// in, so a sound (or the audio mode) that failed once is retried next time
// instead of a partial map being cached as final. Silent switch wins on iOS.
function ensureLoaded(): Promise<void> {
  const missing = (Object.keys(SOURCES) as SoundName[]).filter((name) => !loaded[name]);
  if (audioModeSet && missing.length === 0) return Promise.resolve();
  if (!inFlight) {
    inFlight = (async () => {
      const { Audio, InterruptionModeAndroid } = require('expo-av') as typeof import('expo-av');
      if (!audioModeSet) {
        await Audio.setAudioModeAsync({
          playsInSilentModeIOS: false,
          // Walk cues must sound with the screen off / app backgrounded.
          // Android: the GPS foreground service keeps the process alive.
          // iOS caveat: this only works if Info.plist UIBackgroundModes
          // includes "audio"; the location background mode alone keeps the
          // process running but the audio session may be suspended. Check
          // app.json ios.infoPlist on a real device before relying on it.
          staysActiveInBackground: true,
          shouldDuckAndroid: false,
          interruptionModeAndroid: InterruptionModeAndroid.DoNotMix,
        });
        audioModeSet = true;
      }
      await Promise.all(
        missing.map(async (name) => {
          try {
            const { sound } = await Audio.Sound.createAsync(SOURCES[name](), { shouldPlay: false });
            loaded[name] = sound;
          } catch {
            // one broken sound must not silence the rest; retried on a later play
          }
        })
      );
    })()
      .catch(() => {})
      .finally(() => {
        inFlight = null;
      });
  }
  return inFlight;
}

/** Fire-and-forget. No-op when sound is off or on web; errors swallowed. */
export function play(name: SoundName): void {
  if (Platform.OS === 'web' || !shouldPlay(getFeedbackPrefs(), 'sound')) return;
  ensureLoaded()
    .then(() => loaded[name]?.replayAsync())
    .catch(() => {});
}
